// TeamAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type TeamAuditPolicy struct {
	_ [0]*Team
	// ID controls the audit representation of stored teams.id.
	ID record.Disclosure
	// Name controls the audit representation of stored teams.name.
	Name record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes TeamChanges) Audit(policy TeamAuditPolicy) (record.Model[Team, model.ID[Team]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Team, model.ID[Team]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Team, model.ID[Team]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Team, model.ID[Team]]{}, err
	}
	var captured record.Field[Team]
	captured, err = record.CaptureField[Team]("id", codec.ID[Team](), changes.fields.ID, policy.ID)
	if err != nil {
		return record.Model[Team, model.ID[Team]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Team, model.ID[Team]]{}, err
	}
	captured, err = record.CaptureField[Team]("name", codec.String[string](), changes.fields.Name, policy.Name)
	if err != nil {
		return record.Model[Team, model.ID[Team]]{}, err
	}
	if err = builder.Add(captured); err != nil {
		return record.Model[Team, model.ID[Team]]{}, err
	}
	return builder.Build()
}

